UPDATE conversations c SET next_seq = (SELECT COALESCE(MAX(m.seq), 0) FROM messages m WHERE m.conversation_id = c.id) WHERE c.type = 'DIRECT';

UPDATE conversations SET next_seq = 3 WHERE id = '00000005-0000-4000-8000-000000000050' AND next_seq < 3;

