INSERT INTO posts (id, author_id, group_id, status, body, published_at, created_at, updated_at) VALUES
  ('00000003-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000003', '00000002-0000-4000-8000-000000000001', 'PUBLISHED', 'Сегодня сделал первый длинный маршрут без остановок. Спокойно и приятно.', now() - interval '1 days', now() - interval '1 days', now() - interval '1 days'),
  ('00000003-0000-4000-8000-000000000002', '00000001-0000-4000-8000-000000000008', NULL, 'PUBLISHED', 'Кто подскажет хорошую книгу про город? Хочется чего-нибудь неспешного.', now() - interval '4 days', now() - interval '4 days', now() - interval '4 days'),
  ('00000003-0000-4000-8000-000000000003', '00000001-0000-4000-8000-00000000000d', '00000002-0000-4000-8000-000000000002', 'PUBLISHED', 'Попробовал новый рецепт хлеба — получилось немного кисло, но съедобно.', now() - interval '7 days', now() - interval '7 days', now() - interval '7 days'),
  ('00000003-0000-4000-8000-000000000004', '00000001-0000-4000-8000-000000000012', NULL, 'PUBLISHED', 'Утренняя пробежка в тумане: очень атмосферно.', now() - interval '10 days', now() - interval '10 days', now() - interval '10 days'),
  ('00000003-0000-4000-8000-000000000005', '00000001-0000-4000-8000-000000000017', NULL, 'PUBLISHED', 'Собрали вечером пять партий подряд. Лучший вечер недели.', now() - interval '13 days', now() - interval '13 days', now() - interval '13 days'),
  ('00000003-0000-4000-8000-000000000006', '00000001-0000-4000-8000-000000000004', '00000002-0000-4000-8000-000000000003', 'PUBLISHED', 'Учусь писать тесты — оказалось, что это тоже интересно.', now() - interval '16 days', now() - interval '16 days', now() - interval '16 days'),
  ('00000003-0000-4000-8000-000000000007', '00000001-0000-4000-8000-000000000009', NULL, 'PUBLISHED', 'Акварель всё-таки капризный материал, но результат радует.', now() - interval '19 days', now() - interval '19 days', now() - interval '19 days'),
  ('00000003-0000-4000-8000-000000000008', '00000001-0000-4000-8000-00000000000e', NULL, 'PUBLISHED', 'Нашёл хороший маршрут вдоль реки, делюсь в комментариях.', now() - interval '2 days', now() - interval '2 days', now() - interval '2 days'),
  ('00000003-0000-4000-8000-000000000009', '00000001-0000-4000-8000-000000000013', '00000002-0000-4000-8000-000000000001', 'PUBLISHED', 'Посадил на балконе базилик. Посмотрим, выживет ли.', now() - interval '5 days', now() - interval '5 days', now() - interval '5 days'),
  ('00000003-0000-4000-8000-00000000000a', '00000001-0000-4000-8000-000000000018', NULL, 'PUBLISHED', 'Старый фильм посмотрел в кинотеатре — зал полон, это редкость.', now() - interval '8 days', now() - interval '8 days', now() - interval '8 days'),
  ('00000003-0000-4000-8000-00000000000b', '00000001-0000-4000-8000-000000000005', NULL, 'PUBLISHED', 'Черновик рассказа готов наполовину. Пишу по утрам.', now() - interval '11 days', now() - interval '11 days', now() - interval '11 days'),
  ('00000003-0000-4000-8000-00000000000c', '00000001-0000-4000-8000-00000000000a', '00000002-0000-4000-8000-000000000002', 'PUBLISHED', 'Разобрал старый приёмник, нашёл неисправный конденсатор.', now() - interval '14 days', now() - interval '14 days', now() - interval '14 days'),
  ('00000003-0000-4000-8000-00000000000d', '00000001-0000-4000-8000-00000000000f', NULL, 'PUBLISHED', 'Вечер с пазлом на тысячу деталей. Вот уже третий день.', now() - interval '17 days', now() - interval '17 days', now() - interval '17 days'),
  ('00000003-0000-4000-8000-00000000000e', '00000001-0000-4000-8000-000000000014', NULL, 'PUBLISHED', 'Подборка треков для долгой дороги готова, присылайте свои.', now() - interval '20 days', now() - interval '20 days', now() - interval '20 days'),
  ('00000003-0000-4000-8000-00000000000f', '00000001-0000-4000-8000-000000000001', '00000002-0000-4000-8000-000000000003', 'PUBLISHED', 'Гуляли с собакой до заката, наконец-то стало тепло.', now() - interval '3 days', now() - interval '3 days', now() - interval '3 days'),
  ('00000003-0000-4000-8000-000000000010', '00000001-0000-4000-8000-000000000006', NULL, 'PUBLISHED', 'Ночное небо сегодня очень чистое: видно туманность.', now() - interval '6 days', now() - interval '6 days', now() - interval '6 days'),
  ('00000003-0000-4000-8000-000000000099', '00000001-0000-4000-8000-000000000007', NULL, 'DRAFT', 'Черновик: заметки для следующей записи', NULL, now(), now())
